def copy_location_into_pickup_address(apps, schema_editor):  # noqa: ARG001
    """Existing ads had one free-text location. Keep it as the address line, so the
    Self Pickup block still shows it. Area, city and pincode stay blank until the
    owner fills them in."""
    asset_model = apps.get_model("rental", "RentalAsset")
    for asset in asset_model.objects.filter(pickup_address_line="").exclude(location_text=""):
        asset.pickup_address_line = asset.location_text
        asset.save(update_fields=("pickup_address_line",))


